/**
 * Guards for the ids a change points at (assignees, leads, labels, parent
 * issues, parent comments, mentions).
 *
 * Everything a change references must be usable from the actor's org. A
 * reference owned by another org is refused exactly like any other
 * cross-tenant access (`TenantScopeError` via `assertOrgScope`); anything
 * missing, archived, not a current member or otherwise out of place is
 * refused as `NotFoundError`. Every guard runs before the write, so a refused
 * change leaves nothing behind.
 */
import { isArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import { NotFoundError } from "./_support";
import type { Comment } from "@/types/comment";
import type {
  CommentId,
  IssueId,
  LabelId,
  OrgId,
  UserId,
} from "@/types/common";
import type { Issue } from "@/types/issue";
import type { Actor, Member, MemberWithUser } from "@/types/member";

/** Page size used when scanning an org's full member list. */
const MEMBER_SCAN_PAGE = 100;

function isCurrentMember(member: Member | null): member is Member {
  return member !== null && member.archivedAt === null && member.status === "active";
}

/** A user may be assigned / lead / be mentioned only as a current member. */
export async function assertCurrentMember(
  orgId: OrgId,
  userId: UserId,
  entity = "Member",
): Promise<Member> {
  const member = await memberRepo.findMember(orgId, userId);
  if (!isCurrentMember(member)) throw new NotFoundError(entity, userId);
  return member;
}

/** Every label must be one of the org's own labels. */
export async function assertOwnLabels(
  actor: Actor,
  orgId: OrgId,
  labelIds: readonly LabelId[],
): Promise<void> {
  if (labelIds.length === 0) return;

  const owners = await labelRepo.findLabelOwners(labelIds);
  const ownerOf = new Map(owners.map((owner) => [owner.id, owner.orgId]));

  for (const labelId of labelIds) {
    const owner = ownerOf.get(labelId);
    if (owner === undefined) throw new NotFoundError("Label", labelId);
    assertOrgScope(actor, owner);
    if (owner !== orgId) throw new NotFoundError("Label", labelId);
  }
}

/** A parent issue must be a live issue of the same project. */
export async function assertValidParentIssue(
  actor: Actor,
  orgId: OrgId,
  projectId: Issue["projectId"],
  parentId: IssueId,
): Promise<Issue> {
  const parent = await issueRepo.findIssueById(orgId, parentId);
  if (parent === null) {
    const owner = await issueRepo.findIssueOwner(parentId);
    if (owner !== null) assertOrgScope(actor, owner.orgId);
    throw new NotFoundError("Issue", parentId);
  }
  if (isArchived(parent) || parent.projectId !== projectId) {
    throw new NotFoundError("Issue", parentId);
  }
  return parent;
}

/** A reply must be to a live, top-level comment on the same issue. */
export async function assertValidParentComment(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
  parentId: CommentId,
): Promise<Comment> {
  const parent = await commentRepo.findCommentById(orgId, parentId);
  if (parent === null) {
    const owner = await commentRepo.findCommentOwner(parentId);
    if (owner !== null) assertOrgScope(actor, owner.orgId);
    throw new NotFoundError("Comment", parentId);
  }
  if (
    isArchived(parent) ||
    parent.issueId !== issueId ||
    parent.parentId !== null
  ) {
    throw new NotFoundError("Comment", parentId);
  }
  return parent;
}

/** Every current member of the org, joined with the user record. */
export async function listCurrentMembers(
  orgId: OrgId,
): Promise<readonly MemberWithUser[]> {
  const all: MemberWithUser[] = [];
  let cursor: string | null = null;

  do {
    const page = await memberRepo.listMembers({
      orgId,
      limit: MEMBER_SCAN_PAGE,
      cursor,
    });
    all.push(...page.items);
    cursor = page.nextCursor;
  } while (cursor !== null);

  return all.filter((member) => isCurrentMember(member));
}

