import { afterAll, beforeAll, expect, it, vi } from "vitest";
vi.mock("@/lib/id", () => import("./server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("./server/_support/doubles/misc")).loggerModule);
import * as issueService from "@/server/services/issue-service";
import * as commentService from "@/server/services/comment-service";
import * as labelRepo from "@/server/repositories/label-repository";
import { TenantScopeError } from "@/lib/tenant";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, issueInput, useTemporaryDatabase } from "./server/_support/fixtures";
let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());
it("refs", async () => {
  const a = await createTenant("aa"); const b = await createTenant("bb");
  const bl = await labelRepo.insertLabel({ orgId: b.org.id, name: "x", color: "#000000", description: null } as never);
  await expect(issueService.createIssue(a.actors.owner, { ...issueInput(a.org.id, a.project.id), labelIds: [bl.id] })).rejects.toBeInstanceOf(TenantScopeError);
  await expect(issueService.createIssue(a.actors.owner, issueInput(a.org.id, a.project.id, { assigneeId: b.userIds.owner }))).rejects.toBeInstanceOf(NotFoundError);
  const bi = await issueService.createIssue(b.actors.owner, issueInput(b.org.id, b.project.id));
  await expect(issueService.createIssue(a.actors.owner, { ...issueInput(a.org.id, a.project.id), parentId: bi.id })).rejects.toBeInstanceOf(TenantScopeError);
  const ai = await issueService.createIssue(a.actors.owner, issueInput(a.org.id, a.project.id));
  const c = await commentService.createComment(a.actors.owner, { orgId: a.org.id, issueId: ai.id, body: "hi @member @owner", parentId: null, mentionedUserIds: [b.userIds.owner] });
  expect(c.mentionedUserIds).toEqual(expect.arrayContaining([a.userIds.member, a.userIds.owner]));
  expect(c.mentionedUserIds).not.toContain(b.userIds.owner);
  const r = await commentService.createComment(a.actors.owner, { orgId: a.org.id, issueId: ai.id, body: "r", parentId: c.id, mentionedUserIds: [] });
  await expect(commentService.createComment(a.actors.owner, { orgId: a.org.id, issueId: ai.id, body: "r", parentId: r.id, mentionedUserIds: [] })).rejects.toBeInstanceOf(NotFoundError);
});
EOF
